import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const C=JSON.parse('{"title":"OCR 状态词与回链规范","description":"","frontmatter":{},"headers":[],"relativePath":"OCR资料/OCR 状态词与回链规范.md","filePath":"OCR资料/OCR 状态词与回链规范.md","lastUpdated":1777893104000}'),o={name:"OCR资料/OCR 状态词与回链规范.md"};function r(c,l,h,t,n,_){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="ocr-状态词与回链规范" tabindex="-1">OCR 状态词与回链规范 <a class="header-anchor" href="#ocr-状态词与回链规范" aria-label="Permalink to “OCR 状态词与回链规范”">​</a></h1><ul><li>分类：OCR工程规范</li><li>子系统：状态词统一 / 编号映射 / 证据回链 / 专题互链</li><li>关键词标签：OCR, 状态词, 回链, 编号映射, 证据链, 规范</li><li>来源类型：知识库维护规范</li><li>证据等级：内部工程规范</li><li>完整度状态：深度整理</li><li>关联文档： <ul><li><code>docs/OCR资料/OCR 完整化总表.md</code></li></ul></li><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li><code>docs/OCR 完整化推进清单.md</code></li><li>最后更新：2026-04-20</li></ul><p>本文用于统一 OCR 目录中的状态词、回链方式和维护习惯，减少后续补档时的表述漂移。</p><hr><h2 id="_1-统一状态词" tabindex="-1">1. 统一状态词 <a class="header-anchor" href="#_1-统一状态词" aria-label="Permalink to “1. 统一状态词”">​</a></h2><p>全库统一使用以下状态词：</p><ul><li>已入档</li><li>已入档（待复核）</li><li>无有效文本</li><li>疑似重复页</li><li>备份文件（<code>.hwbk</code>）</li><li>待处理</li></ul><h3 id="_1-1-释义" tabindex="-1">1.1 释义 <a class="header-anchor" href="#_1-1-释义" aria-label="Permalink to “1.1 释义”">​</a></h3><ul><li><code>已入档</code>：已有稳定 OCR 条目，可直接作为知识库证据引用</li><li><code>已入档（待复核）</code>：已有条目，但在 OCR 识别、版本归属、主题细节等方面仍需校正</li><li><code>无有效文本</code>：当前 OCR 无法提取稳定文本，不代表图片本身完全无价值</li><li><code>疑似重复页</code>：与其他页面高度重复，通常只需保留主证据页并建立引用</li><li><code>备份文件（.hwbk）</code>：仅表示文件存在，不纳入主图 OCR 统计</li><li><code>待处理</code>：已知有图或编号，但尚未建立稳定条目</li></ul><h3 id="_1-2-禁止混用的旧说法" tabindex="-1">1.2 禁止混用的旧说法 <a class="header-anchor" href="#_1-2-禁止混用的旧说法" aria-label="Permalink to “1.2 禁止混用的旧说法”">​</a></h3><p>后续尽量不要再单独使用这些松散词：</p><ul><li>无效页</li><li>无文字页</li><li>重复校对页</li><li>待补页</li><li>待补专题</li></ul><p>如必须出现，应同步换写为统一状态词。</p><hr><h2 id="_2-三段式回链标准" tabindex="-1">2. 三段式回链标准 <a class="header-anchor" href="#_2-三段式回链标准" aria-label="Permalink to “2. 三段式回链标准”">​</a></h2><p>高价值主题建议至少建立下面三段式回链：</p><ol><li>来源截图编号</li><li>对应 OCR 文档</li><li>对应专题文档 / 索引文档</li></ol><p>推荐格式：</p><ul><li>来源截图编号：<code>112406, 112424, 112435</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应专题文档：<code>docs/脚本系统/专题研究/创游世界战斗系统设计入门.md</code></li></ul><p>这样可实现：</p><ul><li>从专题反查证据页</li><li>从 OCR 页反查解释文档</li><li>从映射表统一维护主题归属</li></ul><hr><h2 id="_3-文档层级分工" tabindex="-1">3. 文档层级分工 <a class="header-anchor" href="#_3-文档层级分工" aria-label="Permalink to “3. 文档层级分工”">​</a></h2><h3 id="_3-1-ocr-原文归档层" tabindex="-1">3.1 OCR 原文归档层 <a class="header-anchor" href="#_3-1-ocr-原文归档层" aria-label="Permalink to “3.1 OCR 原文归档层”">​</a></h3><p>用于保留截图 OCR 原文、人工整理和关键词。</p><h3 id="_3-2-映射层" tabindex="-1">3.2 映射层 <a class="header-anchor" href="#_3-2-映射层" aria-label="Permalink to “3.2 映射层”">​</a></h3><p>用于建立“编号 → 主题 → 文档 → 状态”的索引关系。</p><h3 id="_3-3-专题层" tabindex="-1">3.3 专题层 <a class="header-anchor" href="#_3-3-专题层" aria-label="Permalink to “3.3 专题层”">​</a></h3><p>用于对多页 OCR 证据进行解释、归纳、教学化表达。</p><h3 id="_3-4-总览-推进层" tabindex="-1">3.4 总览 / 推进层 <a class="header-anchor" href="#_3-4-总览-推进层" aria-label="Permalink to “3.4 总览 / 推进层”">​</a></h3><p>用于说明当前做到了哪、还差哪、下一步补什么。</p><hr><h2 id="_4-实操建议" tabindex="-1">4. 实操建议 <a class="header-anchor" href="#_4-实操建议" aria-label="Permalink to “4. 实操建议”">​</a></h2><ol><li>先记编号，再补 OCR，再回填专题</li><li>重复页优先标主证据页，不强求全文重复录入</li><li>信息主体可用但细节有噪声时，优先标 <code>已入档（待复核）</code></li><li>若专题已成文，务必把截图编号回写到专题头部</li><li>若 OCR 文档已补高价值新页，务必同步更新映射表</li></ol><hr><h2 id="_5-当前最值得优先执行的补全方向" tabindex="-1">5. 当前最值得优先执行的补全方向 <a class="header-anchor" href="#_5-当前最值得优先执行的补全方向" aria-label="Permalink to “5. 当前最值得优先执行的补全方向”">​</a></h2><ol><li>官方教程剩余高价值页的状态化</li><li>脚本截图编号段的继续回填</li><li>引擎更新版本页的“版本号 → 截图编号 → 功能点”闭环</li><li>高价值专题统一补齐来源截图编号与 OCR 回链</li></ol>',37)])])}const O=i(o,[["render",r]]);export{C as __pageData,O as default};
